    pub fn unholed(mut xs: Sexps) -> Sexps {
        loop {
            if null_p(xs) {
                return nil::<&'static Sexp>();
            } else if draft_hole_p(car(xs)) {
                xs = cdr(xs);
                continue;
            } else {
                return kayak_rt::heap_cons(car(xs), unholed(cdr(xs)));
            }
        }
    }

